import { expect, test, uniqueName } from "../../fixtures";

const CASES = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

function isoDateFromToday(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() + days);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

for (const { days, include } of CASES) {
  test(`insurance expiring in ${days} days ${include ? "is" : "is not"} flagged as expiring soon`, { tag: "@REV-08" }, async ({ apiAs }) => {
    const member = await apiAs("member");

    const create = await member.post("/api/vendors", {
      data: { name: uniqueName("Flag Vendor"), category: "logistics", contact_email: "ops@flagvendor.example" },
    });
    expect(create.status(), await create.text()).toBe(201);
    const vendor = await create.json();

    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "insurance.txt", mimeType: "text/plain", buffer: Buffer.from(insuranceText(isoDateFromToday(days))) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    const doc = await upload.json();

    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${doc.id}`);
          return (await res.json()).status;
        },
        { timeout: 30_000 },
      )
      .toBe("extracted");

    const res = await member.get(`/api/vendors/${vendor.id}`);
    expect(res.status(), await res.text()).toBe(200);
    const body = await res.json();
    if (include) {
      expect(body.flags, JSON.stringify(body)).toContain("insurance_expiring_soon");
    } else {
      expect(body.flags, JSON.stringify(body)).not.toContain("insurance_expiring_soon");
    }
  });
}
